import java.util.*;
import java.io.*;

public class Main {
    static long[] chooseProperties(long[] ids, String[] hoods, int[] caps, int groupSize, String target) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int n = Integer.parseInt(st.nextToken());
        long[] ids = new long[n];
        String[] hoods = new String[n];
        int[] caps = new int[n];
        for (int i = 0; i < n; i++) {
            ids[i] = Long.parseLong(st.nextToken());
            hoods[i] = st.nextToken();
            caps[i] = Integer.parseInt(st.nextToken());
        }
        int groupSize = Integer.parseInt(st.nextToken());
        String target = st.nextToken();
        long[] res = chooseProperties(ids, hoods, caps, groupSize, target);
        if (res.length == 0) {
            System.out.println(-1);
        } else {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
            System.out.print(sb);
        }
    }
}
